LineComment.Text:
//Cylinder19 IO  D-washer Loading Horizontal
//Input
"ST10Cylinder".Cy[19].In.WorkPositionSensor := ("D-washer Loading Cylinder Middle Cylinder InHP" AND "D-washer Loading Horizontal Cylinder InWP")
                                            OR ("D-washer Loading Cylinder Middle Cylinder InWP" AND "D-washer Loading Horizontal Cylinder InWP1");
"ST10Cylinder".Cy[19].In.HomePositionSensor := "D-washer Loading Horizontal Cylinder InHP";
//Output
"D-washer Loading Horizontal Cylinder ToWP" := "ST10Cylinder".Cy[19].Out.GoWorkPosition;
"D-washer Loading Horizontal Cylinder ToHP" := "ST10Cylinder".Cy[19].Out.GoHomePosition;

//Cylinder20 IO  D-washer Loading Cylinder Middle
//Input
"ST10Cylinder".Cy[20].In.WorkPositionSensor := "D-washer Loading Cylinder Middle Cylinder InWP";
"ST10Cylinder".Cy[20].In.HomePositionSensor := "D-washer Loading Cylinder Middle Cylinder InHP";
//Output
"D-washer Loading Cylinder Middle Cylinder ToWP" := "ST10Cylinder".Cy[20].Out.GoWorkPosition;
"D-washer Loading Cylinder Middle Cylinder ToHP" := "ST10Cylinder".Cy[20].Out.GoHomePosition;
